package it.gruppoinit.pal.gp.core.domain;

import java.util.HashSet;
import java.util.Set;

import javax.persistence.Column;
import javax.persistence.Entity;
import javax.persistence.FetchType;
import javax.persistence.Id;
import javax.persistence.OneToMany;
import javax.persistence.Table;
import javax.persistence.Transient;

import org.hibernate.validator.Length;

/**
 * RiCariche generated by hbm2java
 */
@Entity
@Table(name = "RI_CARICHE")
public class RiCariche implements java.io.Serializable {

    private static final long serialVersionUID = 3853040804636722373L;
    private String codice;
    private String descrizione;
    private Set<Tipisoggetto> tipisoggettos = new HashSet<Tipisoggetto>(0);

    public RiCariche() {

    }

    @Id
    @Column(name = "CODICE", unique = true, nullable = false, length = 5)
    public String getCodice() {

	return this.codice;
    }

    public void setCodice(String codice) {

	this.codice = codice;
    }

    @Length(max = 150)
    @Column(name = "DESCRIZIONE", length = 150)
    public String getDescrizione() {

	return this.descrizione;
    }

    public void setDescrizione(String descrizione) {

	this.descrizione = descrizione;
    }

    @OneToMany(fetch = FetchType.LAZY, mappedBy = "riCariche")
    public Set<Tipisoggetto> getTipisoggettos() {

	return this.tipisoggettos;
    }

    public void setTipisoggettos(Set<Tipisoggetto> tipisoggettos) {

	this.tipisoggettos = tipisoggettos;
    }

    @Transient
    public String getDescrizioneEstesa() {

	if (getCodice() != null) {
	    return getDescrizione() + " (" + getCodice() + ")";
	}
	return getDescrizione();
    }
}
